insert into public.exercises (id, name, muscle, equipment, category, instructions) values
(pg_temp.sid('ex:Barbell bench press'),'Barbell bench press','Chest','Barbell','strength','Feet planted, shoulder blades pinched, lower the bar to mid-chest and press up.'),
(pg_temp.sid('ex:Incline barbell bench press'),'Incline barbell bench press','Chest','Barbell','strength','Bench at 30 degrees, bar to upper chest, elbows about 45 degrees from the body.'),
(pg_temp.sid('ex:Dumbbell bench press'),'Dumbbell bench press','Chest','Dumbbells','strength','Lower the dumbbells to chest level with control, press up and slightly together.'),
(pg_temp.sid('ex:Incline dumbbell press'),'Incline dumbbell press','Chest','Dumbbells','strength','Bench at 30 degrees, press from upper chest, keep wrists stacked over elbows.'),
(pg_temp.sid('ex:Dumbbell fly'),'Dumbbell fly','Chest','Dumbbells','strength','Soft elbows, open wide until you feel a chest stretch, hug back up.'),
(pg_temp.sid('ex:Cable crossover'),'Cable crossover','Chest','Cable','strength','Step forward, bring handles together in a wide arc in front of the chest.'),
(pg_temp.sid('ex:Machine chest press'),'Machine chest press','Chest','Machine','strength','Handles at mid-chest, press without locking out hard, control the return.'),
(pg_temp.sid('ex:Push-up'),'Push-up','Chest','Bodyweight','strength','Hands under shoulders, body in one line, chest to just above the floor.'),
(pg_temp.sid('ex:Dips'),'Dips','Chest','Bodyweight','strength','Lean slightly forward, lower until shoulders are level with elbows, press up.'),
(pg_temp.sid('ex:Deadlift'),'Deadlift','Back','Barbell','strength','Bar over mid-foot, flat back, push the floor away and stand tall.'),
(pg_temp.sid('ex:Barbell row'),'Barbell row','Back','Barbell','strength','Hinge to 45 degrees, pull the bar to the lower ribs, control down.'),
(pg_temp.sid('ex:Pull-up'),'Pull-up','Back','Bodyweight','strength','Overhand grip, pull chest toward the bar, full hang at the bottom.'),
(pg_temp.sid('ex:Chin-up'),'Chin-up','Back','Bodyweight','strength','Underhand grip, drive elbows down, chin over the bar.'),
(pg_temp.sid('ex:Lat pulldown'),'Lat pulldown','Back','Cable','strength','Slight lean back, pull the bar to the upper chest, elbows down and in.'),
(pg_temp.sid('ex:Seated cable row'),'Seated cable row','Back','Cable','strength','Tall chest, row the handle to the stomach, squeeze shoulder blades.'),
(pg_temp.sid('ex:Single-arm dumbbell row'),'Single-arm dumbbell row','Back','Dumbbells','strength','Hand and knee on bench, row the dumbbell to the hip.'),
(pg_temp.sid('ex:T-bar row'),'T-bar row','Back','Barbell','strength','Chest up, row the handle to the chest, keep the back flat.'),
(pg_temp.sid('ex:Face pull'),'Face pull','Shoulders','Cable','strength','Rope at face height, pull to the forehead with elbows high, rotate out.'),
(pg_temp.sid('ex:Inverted row'),'Inverted row','Back','Bodyweight','strength','Body straight under a bar, pull chest to the bar.'),
(pg_temp.sid('ex:Straight-arm pulldown'),'Straight-arm pulldown','Back','Cable','strength','Arms long, sweep the bar down to the thighs using the lats.'),
(pg_temp.sid('ex:Overhead press'),'Overhead press','Shoulders','Barbell','strength','Bar from the front rack, press overhead, head through at the top.'),
(pg_temp.sid('ex:Seated dumbbell shoulder press'),'Seated dumbbell shoulder press','Shoulders','Dumbbells','strength','Back supported, press from ear height to overhead.'),
(pg_temp.sid('ex:Arnold press'),'Arnold press','Shoulders','Dumbbells','strength','Start palms facing you, rotate out as you press overhead.'),
(pg_temp.sid('ex:Lateral raise'),'Lateral raise','Shoulders','Dumbbells','strength','Slight bend in elbows, raise out to shoulder height, slow down.'),
(pg_temp.sid('ex:Rear delt fly'),'Rear delt fly','Shoulders','Dumbbells','strength','Hinge forward, raise arms out wide leading with the elbows.'),
(pg_temp.sid('ex:Landmine press'),'Landmine press','Shoulders','Barbell','strength','Half-kneeling, press the bar end up and forward.'),
(pg_temp.sid('ex:Push press'),'Push press','Shoulders','Barbell','strength','Short dip at the knees, drive with the legs and press overhead.'),
(pg_temp.sid('ex:Back squat'),'Back squat','Quads','Barbell','strength','Bar on upper back, brace, sit down between the hips, drive up.'),
(pg_temp.sid('ex:Front squat'),'Front squat','Quads','Barbell','strength','Bar in front rack, elbows high, squat upright.'),
(pg_temp.sid('ex:Goblet squat'),'Goblet squat','Quads','Kettlebell','strength','Hold the weight at the chest, squat deep with an upright torso.'),
(pg_temp.sid('ex:Leg press'),'Leg press','Quads','Machine','strength','Feet shoulder width, lower until knees are near 90 degrees, press.'),
(pg_temp.sid('ex:Bulgarian split squat'),'Bulgarian split squat','Quads','Dumbbells','strength','Rear foot on bench, drop the back knee, drive through the front heel.'),
(pg_temp.sid('ex:Walking lunge'),'Walking lunge','Quads','Dumbbells','strength','Long step, back knee toward the floor, step through.'),
